const reconcileExpiredAgentEmailMessageLeases = `-- name: ReconcileExpiredAgentEmailMessageLeases :execrows
UPDATE email_message
SET status = CASE
        WHEN authorized_at IS NOT NULL THEN 'ambiguous'
        WHEN attempt_count >= 20 THEN 'dead'
        ELSE 'queued'
    END,
    next_attempt_at = CASE
        WHEN authorized_at IS NULL AND attempt_count < 20 THEN now()
        ELSE next_attempt_at
    END,
    last_error_code = CASE
        WHEN authorized_at IS NOT NULL THEN 'lease_expired_after_authorization'
        WHEN attempt_count >= 20 THEN COALESCE(last_error_code, 'lease_expired_after_max_attempts')
        ELSE COALESCE(last_error_code, 'lease_expired_before_authorization')
    END,
    completed_at = CASE
        WHEN authorized_at IS NOT NULL OR attempt_count >= 20 THEN now()
        ELSE NULL
    END,
    lease_token = NULL,
    lease_expires_at = NULL,
    updated_at = now()
WHERE workspace_id = $1
  AND status = 'sending'
  AND lease_expires_at <= now()
`

func (q *Queries) ReconcileExpiredAgentEmailMessageLeases(ctx context.Context, workspaceID pgtype.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, reconcileExpiredAgentEmailMessageLeases, workspaceID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

